INSERT INTO site_news (id, category, title, summary, body, published_at)
VALUES
('8aa00000-0000-4000-8000-000000000010', 'update', 'Химическая лаборатория: полноценные эксперименты',
 'Титрование, приготовление растворов и сбор газов на виртуальном лабораторном столе.',
 'В лаборатории доступны измерительные приборы, реактивы, посуда и проведение реакций. Можно наблюдать изменение цвета, появление осадков, выделение газов, работать с индикаторами и измерять количество вещества. Улучшили количественные расчёты и сохранение состава при переливании.', '2026-11-16 12:00:00+00'),
('8aa00000-0000-4000-8000-000000000011', 'update', 'Личные шаблоны досок',
 'Сохраняйте собственные заготовки для повторного использования на уроках.',
 'Раздел шаблонов теперь ориентирован на материалы преподавателя. Сохраните подготовленную доску в качестве личного шаблона, чтобы не создавать её заново для следующего занятия.', '2026-11-15 12:00:00+00'),
('8aa00000-0000-4000-8000-000000000012', 'update', 'Гипербола и графики функций',
 'В математическом редакторе появился дополнительный шаблон графика.',
 'Добавили гиперболу и улучшили вычисление графиков функций. Можно использовать координатную плоскость, формулы и наглядные построения для объяснения темы.', '2026-11-15 10:00:00+00'),
('8aa00000-0000-4000-8000-000000000013', 'update', 'Предложения из слов',
 'Собирайте фразы перетаскиванием карточек на уроке иностранного языка.',
 'В упражнении на построение предложений слова можно перемещать прямо в нужное положение. Управление адаптировано для мыши и сенсорного экрана.', '2026-11-14 12:00:00+00'),
('8aa00000-0000-4000-8000-000000000014', 'feature', 'ИИ-помощник на доске',
 'Помощь в подготовке заданий и управлении учебными объектами.',
 'Добавили предметную поддержку для четырёх приоритетных дисциплин и команды управления объектами доски. Помощник доступен непосредственно в рабочем пространстве занятия.', '2026-11-11 12:00:00+00'),
('8aa00000-0000-4000-8000-000000000015', 'update', 'Линейка, угольник и транспортир',
 'Измерительные инструменты теперь перемещаются вместе с содержимым доски.',
 'Можно разместить инструменты на доске, измерять отрезки и углы, пользоваться ими во время совместного занятия. Они сохраняют своё положение при изменении масштаба и перемещении рабочей области.', '2026-11-01 12:00:00+00'),
('8aa00000-0000-4000-8000-000000000016', 'feature', 'Интерактивные модели по физике',
 'Графики движения, оптические построения и электрические цепи.',
 'Для физики подготовлены отдельные редакторы: график движения с таблицей данных, оптические схемы с построением лучей и инструменты работы с электрическими цепями. Используйте модели для демонстрации и решения задач прямо на доске.', '2026-10-25 12:00:00+00'),
('8aa00000-0000-4000-8000-000000000017', 'feature', 'Геометрические построения',
 'Стройте фигуры по точкам и измеряйте их элементы.',
 'В редакторе геометрии можно создавать и соединять вершины, работать с измерениями и координатами, отменять действия и редактировать фигуры на доске.', '2026-10-24 12:00:00+00'),
('8aa00000-0000-4000-8000-000000000018', 'feature', 'Диаграммы, графика и объёмные фигуры',
 'Больше наглядных элементов для объяснения учебного материала.',
 'В каталоге элементов появились редакторы диаграмм, специальные символы и объёмные геометрические фигуры. Их можно добавлять на доску и редактировать прямо во время занятия.', '2026-10-23 12:00:00+00'),
('8aa00000-0000-4000-8000-000000000019', 'feature', 'Географические задания на сопоставление',
 'Тренируйтесь узнавать страны, столицы, флаги и контуры.',
 'Добавили интерактивное сопоставление пар и учебные карточки по географии. Задания можно подбирать по уровню сложности и использовать на уроке для закрепления материала.', '2026-10-23 10:00:00+00'),
('8aa00000-0000-4000-8000-000000000020', 'update', 'Карты и исторические эпохи',
 'Географические слои, исторические границы и справочная информация в атласе.',
 'Развиваем интерактивный атлас: политические и физические карты, реки, города, рельеф, карточки стран и исторический режим с переключением времени. В октябре добавили региональные данные и географические слои, а также флаги и историческую символику.', '2026-10-22 12:00:00+00')
ON CONFLICT (id) DO NOTHING;
